<?php
declare(strict_types=1);
require __DIR__.'/bootstrap.php';
use EPejabat\Core\{Auth,Database,Authorization,Support,InstallationKey,Accounts};
$p=Database::connect($config['db']);$user=Auth::user($p);if(!$user)Support::redirect('/login');$u=(int)$user['id'];if(!Authorization::super($p,$u)){http_response_code(403);exit('Super Admin diperlukan.');}header('Cache-Control: no-store');
if($_SERVER['REQUEST_METHOD']!=='POST'){echo '<!doctype html><html lang="ms"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Phase 2C preflight</title><h1>Phase 2C compatibility check</h1><p>Semak baseline, payload, ledger dan perlindungan HTTP. Tiada pemasangan atau migration. Percubaan Installation Key dan audit keselamatan direkodkan.</p>'.Support::form('check','<label>Installation Key 12 digit<input type="password" name="key" pattern="[0-9]{12}" maxlength="12" required autocomplete="off"></label>','Semak automatik');exit;}
try{Support::checkCsrf();InstallationKey::verify($p,$u,Support::post('key',12));$stage=__DIR__.'/eforms_package_stage';$manifest=json_decode(file_get_contents($stage.'/manifest.json'),true,512,JSON_THROW_ON_ERROR);$out=['status'=>'PASS','application_files_changed'=>false,'migrations_applied'=>false,'security_audit_logged'=>true,'tests'=>[]];
 $check=static function(string $name,bool $ok,string $reason='')use(&$out):void{$out['tests'][]=['test'=>$name,'status'=>$ok?'PASS':'BLOCKED','reason'=>$reason];if(!$ok)$out['status']='BLOCKED';};
 $check('PHP >= 8.2',version_compare(PHP_VERSION,'8.2.0','>='));foreach(['pdo_mysql','mbstring','fileinfo','openssl','session','zip'] as $ext)$check('extension:'.$ext,extension_loaded($ext));$check('installer lock',is_file(__DIR__.'/storage/installed.lock')&&!is_link(__DIR__.'/storage/installed.lock'));
 foreach($manifest['files'] as $f){$rel=$f['path'];if(!preg_match('/\A(?:app|assets|database)\/[A-Za-z0-9_\/.-]+\z/',$rel)||str_contains($rel,'..'))throw new RuntimeException('Path manifest tidak sah.');$dest=__DIR__.'/'.$rel;$source=$stage.'/payload/'.$rel;$safe=true;foreach([$dest,$source] as $file){for($walk=$file;$walk!==__DIR__&&$walk!==dirname($walk);$walk=dirname($walk))if(is_link($walk))$safe=false;}$target=file_exists($dest)?(is_file($dest)?hash_file('sha256',$dest):'DIRECTORY'):null;$baseline=$target===null?count($f['baseline_sha256'])===0:in_array($target,[...$f['baseline_sha256'],$f['sha256']],true);$payload=$safe&&is_file($source)&&hash_equals($f['sha256'],hash_file('sha256',$source));$check($rel,$payload&&$baseline,!$safe?'SYMLINK':(!$payload?'PAYLOAD_MISMATCH':(!$baseline?'BASELINE_CONFLICT':'MATCH')));}
 foreach($manifest['prerequisites'] as $f){$path=__DIR__.'/'.$f['path'];$check('prerequisite:'.$f['path'],!is_link($path)&&is_file($path)&&in_array(hash_file('sha256',$path),$f['sha256'],true),'Existing Core integration must match.');}
 foreach($manifest['migrations'] as $m){$r=Database::query($p,'SELECT checksum,status FROM database_migrations WHERE version=?',[$m['version']])->fetch();$ok=$r?$r['status']==='applied'&&hash_equals($m['sha256'],$r['checksum']):!$m['required'];$check($m['version'],$ok,$r?'Ledger checked':($m['required']?'MISSING_REQUIRED':'PENDING'));}
 $ledger=Database::query($p,"SELECT status FROM database_migrations WHERE version='eforms:Phase2:210_package_pdf_support.sql'")->fetchColumn();if(!$ledger){foreach(['eforms_pdf_sources','eforms_visual_versions','eforms_delegations','eforms_print_snapshots'] as $table)$check('No untracked table:'.$table,!Database::query($p,'SELECT 1 FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=?',[$table])->fetchColumn());}
 $packageLedger=Database::query($p,"SELECT status FROM database_migrations WHERE version='eforms:Phase2:211_form_packages.sql'")->fetchColumn();if(!$packageLedger)foreach(['eforms_package_stages','eforms_package_forms','eforms_package_imports'] as $table)$check('No untracked table:'.$table,!Database::query($p,'SELECT 1 FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=?',[$table])->fetchColumn());
 foreach(['app/Modules/EForms','assets','database','database/modules/eforms','storage'] as $dir)$check('Writable:'.$dir,is_dir(__DIR__.'/'.$dir)&&!is_link(__DIR__.'/'.$dir)&&is_writable(__DIR__.'/'.$dir));
 $check('e-Forms module active',Database::query($p,"SELECT status FROM module_registry WHERE module_key='eforms'")->fetchColumn()==='active');
 $out['versions']=Database::query($p,"SELECT setting_key,setting_value FROM system_settings WHERE setting_key IN ('app_version','core_version','module_version.eforms','module_version.training')")->fetchAll();
 $origin=Accounts::origin();$a=parse_url($origin);if(!function_exists('curl_init')||($a['scheme']??'')!=='https'||strtolower($a['host']??'')!==strtolower($_SERVER['HTTP_HOST']??''))$check('Private HTTP deny verification',false,'Requires cURL and configured HTTPS production origin.');else foreach(['/app/Core/Database.php','/database/modules/eforms/200_eforms_schema.sql','/storage/installed.lock','/eforms_package_stage/manifest.json'] as $url){$ch=curl_init($origin.$url);curl_setopt_array($ch,[CURLOPT_NOBODY=>true,CURLOPT_RETURNTRANSFER=>true,CURLOPT_FOLLOWLOCATION=>false,CURLOPT_CONNECTTIMEOUT=>5,CURLOPT_TIMEOUT=>8,CURLOPT_SSL_VERIFYPEER=>true,CURLOPT_SSL_VERIFYHOST=>2,CURLOPT_PROTOCOLS=>CURLPROTO_HTTPS]);curl_exec($ch);$status=(int)curl_getinfo($ch,CURLINFO_RESPONSE_CODE);curl_close($ch);$check('HTTP deny:'.$url,in_array($status,[403,404],true),'HTTP '.$status);}
 unset($_SESSION['upgrade_key_auth']);header('Content-Type: application/json');echo json_encode($out,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR);
}catch(Throwable $e){unset($_SESSION['upgrade_key_auth']);http_response_code(400);header('Content-Type: application/json');echo json_encode(['status'=>'BLOCKED','message'=>$e instanceof PDOException?'Database preflight tidak tersedia.':$e->getMessage()]);}
